[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Product Catalog Performance &amp; Customer Sentiment Analysis</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --brand-blue: #1a3a5c;
    --brand-teal: #0d7377;
    --accent-orange: #e8832a;
    --accent-green: #2e8b57;
    --accent-red: #c0392b;
    --accent-yellow: #f0a500;
    --bg: #f4f6fa;
    --card-bg: #ffffff;
    --border: #dce3ee;
    --text-primary: #1a1e2e;
    --text-secondary: #5a6478;
    --text-light: #8a93a8;
    --shadow: 0 2px 12px rgba(0,0,0,0.07);
    --shadow-hover: 0 6px 24px rgba(0,0,0,0.13);
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg);
    color: var(--text-primary);
    font-size: 15px;
    line-height: 1.6;
  }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, var(--brand-blue) 0%, #0f2744 100%);
    color: white;
    padding: 48px 60px 40px;
    border-bottom: 4px solid var(--brand-teal);
  }
  .report-header .eyebrow {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.55);
    margin-bottom: 10px;
  }
  .report-header h1 {
    font-size: 32px;
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 10px;
    letter-spacing: -0.5px;
  }
  .report-header .subtitle {
    font-size: 15px;
    color: rgba(255,255,255,0.7);
    max-width: 680px;
  }
  .report-header .meta {
    margin-top: 20px;
    font-size: 12px;
    color: rgba(255,255,255,0.45);
    display: flex;
    gap: 24px;
  }
  .report-header .meta span { display: flex; align-items: center; gap: 5px; }

  /* Layout */
  .container { max-width: 1200px; margin: 0 auto; padding: 40px 40px; }

  /* Section headers */
  .section {
    margin-bottom: 52px;
  }
  .section-header {
    display: flex;
    align-items: flex-end;
    gap: 14px;
    margin-bottom: 24px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--border);
  }
  .section-number {
    background: var(--brand-teal);
    color: white;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1px;
    padding: 3px 8px;
    border-radius: 4px;
    margin-bottom: 2px;
  }
  .section-header h2 {
    font-size: 22px;
    font-weight: 700;
    color: var(--brand-blue);
    flex: 1;
  }
  .section-header .section-desc {
    font-size: 13px;
    color: var(--text-light);
    text-align: right;
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 32px;
  }
  .kpi-card {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 22px 18px 20px;
    box-shadow: var(--shadow);
    border-top: 4px solid transparent;
    transition: box-shadow 0.2s;
    position: relative;
    overflow: hidden;
  }
  .kpi-card:hover { box-shadow: var(--shadow-hover); }
  .kpi-card.blue { border-top-color: var(--brand-blue); }
  .kpi-card.teal { border-top-color: var(--brand-teal); }
  .kpi-card.orange { border-top-color: var(--accent-orange); }
  .kpi-card.green { border-top-color: var(--accent-green); }
  .kpi-card.yellow { border-top-color: var(--accent-yellow); }
  .kpi-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--text-light);
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 32px;
    font-weight: 800;
    line-height: 1;
    margin-bottom: 5px;
    letter-spacing: -1px;
  }
  .kpi-card.blue .kpi-value { color: var(--brand-blue); }
  .kpi-card.teal .kpi-value { color: var(--brand-teal); }
  .kpi-card.orange .kpi-value { color: var(--accent-orange); }
  .kpi-card.green .kpi-value { color: var(--accent-green); }
  .kpi-card.yellow .kpi-value { color: var(--accent-yellow); }
  .kpi-sub { font-size: 12px; color: var(--text-secondary); }

  /* Cards */
  .card {
    background: var(--card-bg);
    border-radius: 12px;
    padding: 28px 28px;
    box-shadow: var(--shadow);
    margin-bottom: 20px;
  }
  .card-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--brand-blue);
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .card-title::before {
    content: '';
    display: block;
    width: 4px;
    height: 16px;
    background: var(--brand-teal);
    border-radius: 2px;
  }

  /* Grid layouts */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .grid-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; }

  /* Chart containers */
  .chart-wrap { position: relative; width: 100%; }
  .chart-wrap canvas { max-width: 100%; }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
  }
  thead th {
    background: #f0f3f9;
    padding: 10px 14px;
    text-align: left;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.7px;
    text-transform: uppercase;
    color: var(--text-secondary);
    border-bottom: 2px solid var(--border);
  }
  thead th.right { text-align: right; }
  tbody tr { border-bottom: 1px solid #eef1f7; transition: background 0.1s; }
  tbody tr:hover { background: #f8f9fd; }
  tbody tr:last-child { border-bottom: none; }
  tbody td { padding: 11px 14px; color: var(--text-primary); }
  tbody td.right { text-align: right; }
  tbody td.mono { font-family: 'SF Mono', 'Fira Code', monospace; font-size: 13px; }
  .rank-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    font-size: 11px;
    font-weight: 700;
    margin-right: 6px;
  }
  .rank-1 { background: #ffd700; color: #7a5c00; }
  .rank-2 { background: #c0c0c0; color: #444; }
  .rank-3 { background: #cd7f32; color: #fff; }
  .rank-other { background: #eef1f7; color: var(--text-secondary); }

  /* Rating bar */
  .rating-bar-wrap { display: flex; align-items: center; gap: 8px; }
  .rating-bar-bg { flex: 1; height: 7px; background: #eef1f7; border-radius: 4px; overflow: hidden; }
  .rating-bar-fill { height: 100%; border-radius: 4px; }
  .fill-green { background: var(--accent-green); }
  .fill-teal { background: var(--brand-teal); }
  .fill-orange { background: var(--accent-orange); }
  .fill-red { background: var(--accent-red); }

  /* Insight callouts */
  .insight-box {
    background: #edf7f5;
    border-left: 4px solid var(--brand-teal);
    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    margin-top: 16px;
    font-size: 13.5px;
    color: var(--text-primary);
  }
  .insight-box strong { color: var(--brand-teal); }
  .insight-box.warn { background: #fef6ec; border-left-color: var(--accent-orange); }
  .insight-box.warn strong { color: var(--accent-orange); }
  .insight-box.alert { background: #fdf0ef; border-left-color: var(--accent-red); }
  .insight-box.alert strong { color: var(--accent-red); }

  /* Correlation indicator */
  .corr-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: #fdf0ef;
    border: 1px solid #f0c0bb;
    border-radius: 6px;
    padding: 4px 10px;
    font-size: 12px;
    font-weight: 700;
    color: var(--accent-red);
  }
  .corr-badge.neutral { background: #f0f3f9; border-color: #dce3ee; color: var(--text-secondary); }

  /* Sentiment word cloud style */
  .word-cloud { display: flex; flex-wrap: wrap; gap: 10px; padding: 8px 0; }
  .word-tag {
    display: inline-block;
    padding: 5px 12px;
    border-radius: 20px;
    font-weight: 600;
    font-size: 13px;
  }
  .word-tag.pos { background: #e8f5ee; color: var(--accent-green); border: 1px solid #b2d9c2; }
  .word-tag.neg { background: #fdf0ef; color: var(--accent-red); border: 1px solid #f0c0bb; }

  /* Recommendations */
  .rec-list { display: flex; flex-direction: column; gap: 16px; }
  .rec-item {
    background: var(--card-bg);
    border-radius: 10px;
    padding: 20px 24px;
    box-shadow: var(--shadow);
    display: flex;
    gap: 18px;
    align-items: flex-start;
    border-left: 4px solid var(--brand-teal);
  }
  .rec-item.orange { border-left-color: var(--accent-orange); }
  .rec-item.blue { border-left-color: var(--brand-blue); }
  .rec-item.yellow { border-left-color: var(--accent-yellow); }
  .rec-item.red { border-left-color: var(--accent-red); }
  .rec-num {
    font-size: 28px;
    font-weight: 900;
    color: var(--border);
    line-height: 1;
    min-width: 32px;
  }
  .rec-body h4 { font-size: 15px; font-weight: 700; color: var(--brand-blue); margin-bottom: 5px; }
  .rec-body p { font-size: 13.5px; color: var(--text-secondary); margin-bottom: 6px; }
  .rec-data { font-size: 12px; font-weight: 600; padding: 3px 8px; border-radius: 4px; background: #f0f3f9; color: var(--text-secondary); display: inline-block; }

  /* Footer */
  .report-footer {
    background: var(--brand-blue);
    color: rgba(255,255,255,0.5);
    text-align: center;
    padding: 24px;
    font-size: 12px;
    margin-top: 20px;
  }

  /* Engagement product list */
  .product-row {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 12px 0;
    border-bottom: 1px solid #eef1f7;
  }
  .product-row:last-child { border-bottom: none; }
  .product-rank { font-size: 18px; font-weight: 800; color: var(--border); min-width: 28px; }
  .product-info { flex: 1; }
  .product-name { font-size: 13.5px; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
  .product-cat { font-size: 11px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.5px; }
  .product-stats { text-align: right; }
  .product-rating { font-size: 16px; font-weight: 800; color: var(--accent-green); }
  .product-reviews { font-size: 11px; color: var(--text-light); }
</style>
</head>
