<!-- ═══════════════════════════════════════════════════════ HEADER -->
<div class="report-header">
  <div class="eyebrow">Analytics Report &bull; Amazon India Marketplace</div>
  <h1>Amazon Product Catalog Performance<br>&amp; Customer Sentiment Analysis</h1>
  <div class="subtitle">A comprehensive analysis of 1,465 Amazon products examining pricing strategies, discount effectiveness, customer ratings, and category-level performance to identify optimization opportunities.</div>
  <div class="meta">
    <span>📅 April 2026</span>
    <span>📦 1,465 Products Analyzed</span>
    <span>🎯 Audience: Product &amp; Category Management</span>
    <span>📊 Source: Amazon India Marketplace Snapshot</span>
  </div>
</div>

<div class="container">

<!-- ═══════════════════════════════════════════════════════ SECTION 1: EXECUTIVE OVERVIEW -->
<div class="section">
  <div class="section-header">
    <div>
      <div class="section-number">01</div>
      <h2>Executive Overview</h2>
    </div>
    <div class="section-desc">Headline KPIs &bull; Catalog Snapshot</div>
  </div>

  <!-- KPI Cards -->
  <div class="kpi-grid">
    <div class="kpi-card blue">
      <div class="kpi-label">Avg Product Rating</div>
      <div class="kpi-value">4.1</div>
      <div class="kpi-sub">out of 5.0 &mdash; 1,464 rated products</div>
    </div>
    <div class="kpi-card orange">
      <div class="kpi-label">Avg Discount</div>
      <div class="kpi-value">47.7%</div>
      <div class="kpi-sub">Median offering is nearly half off list price</div>
    </div>
    <div class="kpi-card teal">
      <div class="kpi-label">Median Reviews/Product</div>
      <div class="kpi-value">5,179</div>
      <div class="kpi-sub">Typical customer engagement level</div>
    </div>
    <div class="kpi-card green">
      <div class="kpi-label">High-Rating Share</div>
      <div class="kpi-value">75.8%</div>
      <div class="kpi-sub">1,110 of 1,464 products rated ≥ 4.0</div>
    </div>
    <div class="kpi-card yellow">
      <div class="kpi-label">Discount–Rating Corr.</div>
      <div class="kpi-value">−0.16</div>
      <div class="kpi-sub">Deeper discounts slightly lower ratings</div>
    </div>
  </div>

  <!-- Summary narrative -->
  <div class="grid-2">
    <div class="card">
      <div class="card-title">Catalog at a Glance</div>
      <p style="font-size:14px; color:var(--text-secondary); margin-bottom:12px;">The catalog spans <strong>4 major categories</strong> — Electronics (526 products), Computers &amp; Accessories (453), Home &amp; Kitchen (448), and Office Products (31) — plus 5 minor categories. The catalog is dominated by tech accessories and consumer electronics.</p>
      <p style="font-size:14px; color:var(--text-secondary);">Overall customer satisfaction is high: the average rating of <strong>4.1/5</strong> and 75.8% high-rating share signal a well-curated assortment. However, the negative correlation between discount depth and ratings warrants strategic attention.</p>
      <div class="insight-box">
        <strong>Key Signal:</strong> High-discount products (>80% off) are the lowest-rated segment at 3.98 avg, suggesting quality concerns in aggressive markdown products.
      </div>
    </div>
    <div class="card">
      <div class="card-title">Category Distribution</div>
      <div class="chart-wrap" style="height:220px;">
        <canvas id="catDistChart"></canvas>
      </div>
    </div>
  </div>
</div>

<!-- ═══════════════════════════════════════════════════════ SECTION 2: CATEGORY ANALYSIS -->
<div class="section">
  <div class="section-header">
    <div>
      <div class="section-number">02</div>
      <h2>Category Performance Breakdown</h2>
    </div>
    <div class="section-desc">Rating &bull; Engagement &bull; Discount Intensity</div>
  </div>

  <div class="grid-2">
    <div class="card">
      <div class="card-title">Avg Rating by Category</div>
      <div class="chart-wrap" style="height:260px;">
        <canvas id="catRatingChart"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Avg Discount % by Category</div>
      <div class="chart-wrap" style="height:260px;">
        <canvas id="catDiscountChart"></canvas>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-title">Category Performance Scorecard</div>
    <table>
      <thead>
        <tr>
          <th>Rank</th>
          <th>Category</th>
          <th class="right">Products</th>
          <th class="right">Avg Rating</th>
          <th>Rating Visual</th>
          <th class="right">Avg Discount</th>
          <th class="right">Total Reviews</th>
          <th class="right">Median Reviews</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td><span class="rank-badge rank-1">1</span></td>
          <td><strong>Office Products</strong></td>
          <td class="right mono">31</td>
          <td class="right"><strong style="color:var(--accent-green);">4.31</strong></td>
          <td>
            <div class="rating-bar-wrap">
              <div class="rating-bar-bg"><div class="rating-bar-fill fill-green" style="width:86.2%"></div></div>
              <span style="font-size:11px;color:var(--text-light)">86%</span>
            </div>
          </td>
          <td class="right mono">12.4%</td>
          <td class="right mono">149,675</td>
          <td class="right mono">4,426</td>
        </tr>
        <tr>
          <td><span class="rank-badge rank-2">2</span></td>
          <td><strong>Computers &amp; Accessories</strong></td>
          <td class="right mono">453</td>
          <td class="right"><strong style="color:var(--accent-green);">4.15</strong></td>
          <td>
